const Navbar = (props) => {
  // const [profileitems, setprofileitems] = useState(false);
  const [state, setstate] = useState(false);
  const [color, setcolor] = useState(props.color);

  const [login, setlogin] = useState(true);
  const [user, setuser] = useState([]);

  const [imageexpansion, setimageexpansion] = useState(false);

  const [profilepath, setprofilepath] = useState();

  window.addEventListener("scroll", () =>
    window.scrollY <= 10 ? setcolor(props.color) : setcolor("black")
  );

  const myLoginState = useSelector((state) => state.changeTheLogin);

  console.log("redux login state", myLoginState);
  const callNavbar = async () => {
    try {
      const res = await axios.get(apiUrl + `/getData/${myLoginState}`, {
        withCredentials: true,
      });

      const data = await res.data;
      // console.log(res);
      console.log(data);
      setprofilepath(data.profile);
      setuser(data);
      setlogin(data.name ? false : true);
      if (res.status !== 200) {
        throw new Error(res.error);
      }
    } catch (e) {
      console.log(e);
    }
  };
  // if (user) {
  //   setlogin(false);
  // } else {
  //   setlogin(true);
  // }

  const [profile, setprofile] = useState();
  const [updatedimage, setupdatedimage] = useState([]);

  const handleChange = (file) => {
    const reader = new FileReader();
    reader.readAsDataURL(file.target.files[0]);
    setupdatedimage(file.target.files[0]);
    // console.log(reader.result);
    reader.onload = () => {
      if (reader.readyState == 2) {
        setprofile(reader.result);
      }
    };
  };

  const handleUpload = async () => {
    try {
      const formData = new FormData();
      formData.append("file", updatedimage);
      const res = await axios.post(
        apiUrl + `/profileimage/${myLoginState}`,
        formData,
        {
          withCredentials: true,
        }
      );
      callNavbar();
      setimageexpansion(!imageexpansion);
    } catch (error) {
      console.log(error);
    }
  };

  useEffect(() => {
    callNavbar();
  }, []);

  return (
    <Container bg={color} posi={props.position}>
      <NavLink to="/" className="titlecontainer">
        ONE TOUCH JOB
      </NavLink>
      <div className="hamburger">
        <div className="icon" onClick={() => setstate(!state)}>
          {state ? <i class="fas fa-times"></i> : <i class="fas fa-bars"></i>}
        </div>
      </div>
      <Linkscontainer hamb={state}>
        <ul className="items">
          <li>
            <NavLink
              to="/"
              style={{ textDecoration: "none", color: "transparent" }}
            >
              <p>Home</p>
            </NavLink>
          </li>
          <li>
            <a
              href="#home"
              style={{ textDecoration: "none", color: "transparent" }}
            >
              <p>Services</p>
            </a>
          </li>
          <li>
            <NavLink to="/contact" style={{ textDecoration: "none" }}>
              <p>Contact Us</p>
            </NavLink>
          </li>
          {login ? (
            <li>
              <NavLink to="/login" style={{ textDecoration: "none" }}>
                <p>Sign in</p>
              </NavLink>
            </li>
          ) : (
            ""
          )}
          {login ? (
            <li>
              <NavLink to="/register" style={{ textDecoration: "none" }}>
                <p>Register</p>
              </NavLink>
            </li>
          ) : (
            <li>
              <NavLink to="/logout" style={{ textDecoration: "none" }}>
                <p>Sign Out</p>
              </NavLink>
            </li>
          )}
          {login ? (
            <></>
          ) : (
            <li>
              <div className="profileimage">
                <img
                  src={profilepath ? profilepath : profile1}
                  alt=""
                  className="small"
                  onClick={() => setimageexpansion(!imageexpansion)}
                />
                <div
                  className="imageexpansion"
                  style={{ display: imageexpansion ? "flex" : "none" }}
                >
                  <div className="image">
                    <img
                      src={
                        profile ? profile : profilepath ? profilepath : profile1
                      }
                      alt=""
                      className="large"
                    />
                    <label htmlFor="Fileinput" className="accounticon">
                      <i class="fas fa-plus"></i>{" "}
                    </label>
                  </div>
                  <input
                    type="file"
                    id="Fileinput"
                    style={{ display: "none" }}
                    className="updateprofile"
                    onChange={handleChange}
                  />
                  <button className="updateprofilepic" onClick={handleUpload}>
                    Update profile
                  </button>
                </div>
              </div>
            </li>
          )}
        </ul>
      </Linkscontainer>
    </Container>
  );
};

export default Navbar;
